/**
 * Link's states fixture, with the React fixture's entry names, so a
 * contract's `when <state>` names the same entry in both shells.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/link.ts`. Never edit it by hand.
 */
import { h } from 'vue'

import type { ComponentStates } from '@polymorph/vue'

import Link from './Link.vue'
import Stack from '../layout/Stack.vue'
import Text from '../structure/Text.vue'

export const states: ComponentStates = {
  component: 'Link',
  entries: [
    {
      name: 'inline — underlined inside the sentence it belongs to',
      render: () =>
        h(
          Text,
          {},
          {
            default: () => [
              'Retries stop after the first 5xx; the ',
              h(Link, { href: '#delivery' }, { default: () => ['delivery log'] }),
              ' has the response bodies.',
            ],
          },
        ),
    },
    {
      name: 'standalone — a row, underlined on hover instead',
      render: (overrides = {}) =>
        h(
          Link,
          { href: '#audit', variant: 'standalone', ...overrides },
          { default: () => ['Open the audit trail'] },
        ),
      expect: { 'data-variant': 'standalone' },
    },
    {
      name: 'external — a new tab, a glyph, and the rel that makes it safe',
      render: (overrides = {}) =>
        h(
          Link,
          { href: 'https://example.com/status', external: true, ...overrides },
          { default: () => ['Status page'] },
        ),
      expect: { 'data-external': '', target: '_blank', rel: 'noreferrer' },
    },
    {
      name: 'external and standalone',
      render: (overrides = {}) =>
        h(
          Link,
          { href: 'https://example.com/docs', variant: 'standalone', external: true, ...overrides },
          { default: () => ['Webhook documentation'] },
        ),
    },
    {
      name: 'inherits the step of the text around it',
      render: () =>
        h(
          Stack,
          { gap: 3 },
          {
            default: () => [
              h('p', {}, [
                'A link in body copy is ',
                h(Link, { href: '#a' }, { default: () => ['the same size as the copy'] }),
                '.',
              ]),
            ],
          },
        ),
    },
    {
      name: 'the costume, default — soft, accent, md; navigation holding rank in a row of Buttons',
      render: (overrides = {}) =>
        h(
          Link,
          { href: '#billing', variant: 'button', ...overrides },
          { default: () => ['View billing'] },
        ),
      expect: { 'data-variant': 'soft', 'data-tone': 'accent', 'data-size': 'md' },
    },
    {
      name: 'the costume as solid — a claim chosen into, never defaulted',
      render: (overrides = {}) =>
        h(
          Link,
          { href: '#setup', variant: 'button', buttonVariant: 'solid', ...overrides },
          { default: () => ['Start setup'] },
        ),
      expect: { 'data-variant': 'solid', 'data-tone': 'accent' },
    },
    {
      name: 'the costume as outline neutral',
      render: (overrides = {}) =>
        h(
          Link,
          {
            href: '#docs',
            variant: 'button',
            buttonVariant: 'outline',
            tone: 'neutral',
            ...overrides,
          },
          { default: () => ['Read the docs'] },
        ),
      expect: { 'data-variant': 'outline', 'data-tone': 'neutral' },
    },
    {
      name: 'external in costume — the glyph rides Button’s trailing slot',
      render: (overrides = {}) =>
        h(
          Link,
          {
            href: 'https://example.com/status',
            variant: 'button',
            buttonVariant: 'outline',
            external: true,
            ...overrides,
          },
          { default: () => ['Status page'] },
        ),
      expect: { 'data-external': '', target: '_blank', rel: 'noreferrer' },
    },
  ],
}
